  function validateJob(job,id,{complete=true}={}){if(job.id!==id)throw Error("응답 실행 ID가 요청과 다릅니다.");if(job.plugin_id!=="camera_db_design_study_v1")throw Error("선택 실행은 DB Design Lab 계산이 아닙니다. 원래 작업 화면에서 확인하세요.");if(complete&&job.status!=="succeeded")throw Error("A 비교 기준은 완료된 DB 실행만 선택할 수 있습니다.");if(job.status==="succeeded"){const result=job.result?.summary;if(!Array.isArray(result?.candidates))throw Error("선택 실행에 DB 후보 비교 결과가 없습니다.");if(result.aperture_conditions){const conditions=conditionRows(result);if(result.aperture_conditions.default_condition_id&&!conditions.some(c=>c.id===result.aperture_conditions.default_condition_id))throw Error("기본 광량·노출 조건 ID가 보존 결과와 일치하지 않습니다.");if(!conditions.length||new Set(conditions.map(c=>c.id)).size!==conditions.length||conditions.some(c=>!/^condition-[0-9]{3}$/.test(c.id)||!finite(c.luminance_cd_m2)||(isMotionResult(result)?!finite(c.object_speed_m_s)||c.object_speed_m_s<0||!finite(c.object_distance_m??result.aperture_conditions.object_distance_m)||(c.object_distance_m??result.aperture_conditions.object_distance_m)<=0:!finite(c.exposure_ms))||!Array.isArray(c.candidates)||!c.candidates.length||new Set(c.candidates.map(v=>v.id)).size!==c.candidates.length||c.candidates.some(v=>v.prefix!==`conditions/${c.id}/candidates/${v.id}/`)||!c.aperture_sweep))throw Error("광량·노출 조건 결과의 식별자 또는 지표가 불완전합니다.");}if(result.files_base!==RUNS+encodeURIComponent(job.id)+"/files/")throw Error("결과 파일 경로가 선택 실행 ID와 일치하지 않습니다.");}return job;}
