  function sensorModeMarkup(m,rows=[]){if(!m)return'<p class="muted">직접 입력한 line time 가정입니다. 프레임 주기·FPS·제품 노출 제한은 미확보이며 적용하지 않습니다.</p>';const known=m.classification==="module_manufacturer_driver_derived";return`<h4>${esc(m.label)} <span class="source-badge ${known?"derived":"assumed"}">${known?"확보한 드라이버 값에서 계산":"미확보 timing · 가정"}</span></h4><p>Line time <b>${fmt(m.line_time_us,6)} µs</b> · 프레임 <b>${fmt(m.frame_period_ms,4)} ms</b> · ${fmt(m.actual_fps,3)} FPS<br>HMAX ${fmt(m.hmax)} / clock ${fmt(m.timing_clock_hz/1e6,3)} MHz / VMAX ${fmt(m.vmax)} · ${known?"모듈 제조사 드라이버 근거":"HMAX·clock·VMAX는 가정"}</p><p>요청 노출 ${fmt(m.requested_exposure_min_us/1000,6)}–${fmt(m.requested_exposure_max_us/1000,6)} ms · 1행 단위 양자화 · 고정 FPS 유지. ${known?"FPS 2–30 범위에서 VMAX로 조정; 드라이버의 노출 상한은 유지합니다.":"이 비교 프로필은 표시한 FPS만 지원합니다."}</p>${rows.length?'<table><thead><tr><th>요청 노출 ms</th><th>실제 노출 ms</th><th>적분 행 / SHS1</th><th>결과</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${fmt(r.requested_exposure_ms,6)}</td><td>${fmt(r.actual_exposure_ms,6)}</td><td>${fmt(r.coarse_integration_lines)} / ${fmt(r.shs1_register)}</td><td class="${r.status==="eligible"?"pass":"fail"}">${r.status==="eligible"?"실제 RAW 계산":"차단 · RAW 없음"}<small>${esc((r.reasons||[]).join(" · "))}</small></td></tr>`).join("")+'</tbody></table>':""}<p><a href="${esc(m.source_url)}" target="_blank" rel="noopener">Timing 근거 ↗</a> · ${known?`고정 revision ${esc(m.source_commit)}`:"Sony 최대 FPS는 line time의 근거가 아닙니다."}</p><details><summary>적용 범위·남은 가정</summary><ul>${(m.assumptions||[]).map(v=>`<li>${esc(v)}</li>`).join("")}</ul><p>기존 TechInsights 구조 revision에는 모드별 timing 행이 없습니다. 모듈 드라이버의 timing만 적용하며 기존 구조 모델의 잡음·well·ADC는 유지합니다. 실제 모듈 실측 정합은 미확인입니다.</p></details>`;}
  function renderSensorModeInput(reset=false){const select=$("sensor-shutter-mode"),slot=$("sensor-mode-input");if(!select||!slot)return;const entries=state.options?.sensor_operating_modes?.modes||[];if(!select.dataset.loaded&&entries.length){select.innerHTML='<option value="">직접 설정 · 가정</option>'+entries.map(m=>`<option value="${esc(m.id)}">${esc(m.label)}</option>`).join("");select.value="kurokesu_1080p30_raw10";select.dataset.loaded="true";reset=true;}const m=entries.find(v=>v.id===select.value),fpsInput=$("sensor-shutter-fps");$("sensor-shutter-line-times").disabled=!!m;fpsInput.disabled=!m;if(m){if(reset)fpsInput.value=m.requested_fps;fpsInput.min=m.min_fps;fpsInput.max=m.max_fps;$("sensor-shutter-line-times").value=`0, ${m.line_time_us}`;const fps=Number(fpsInput.value),vmax=Math.max(1125,Math.floor(m.timing_clock_hz/m.hmax/fps));slot.innerHTML=sensorModeMarkup({...m,requested_fps:fps,vmax,frame_period_ms:vmax*m.line_time_us/1000,actual_fps:1e6/(vmax*m.line_time_us)});}else slot.innerHTML=sensorModeMarkup(null);}
  function renderSensorModeResult(){const slot=$("sensor-mode-result");if(!slot)return;const m=state.result?.operating_mode;slot.innerHTML=m?sensorModeMarkup(m,state.result.exposure_schedule||[]):"";if(!m)return;const app=state.result.timing_readout_application;if(app)slot.innerHTML+=`<p class="mode-readout-scope"><b>Timing만 적용:</b> 근거 드라이버 ${fmt(app.source_mode_bit_depth)}bit / 계산 센서 ${fmt(app.simulated_readout?.bit_depth)}bit · read noise ${fmt(app.simulated_readout?.read_noise_e)} e⁻ · well ${fmt(app.simulated_readout?.full_well_e)} e⁻. 회로값은 기존 구조 모델 가정입니다.</p>`;const configuration=state.result.configuration||{},same=v=>["source_run_id","luminance_cd_m2","object_speed_m_s","object_distance_m","exposure_ms","f_numbers","located_source_run_id","selection_policy"].every(k=>JSON.stringify(v[k])===JSON.stringify(configuration[k])),runs=(state.options?.recent_runs||[]).filter(r=>r.status==="succeeded"&&r.operating_mode_id&&r.timing_configuration&&same({...r.timing_configuration,name:configuration.name,operating_mode_id:configuration.operating_mode_id,fps:configuration.fps,line_time_us:configuration.line_time_us}));if(runs.length)slot.innerHTML+='<p class="prepared-mode-runs">완료된 모드 결과 · 같은 광량·속도 / 저장된 기본 노출: '+runs.map(r=>`<a href="/db-design.html?${new URLSearchParams({run:r.id,condition:activeCondition()?.id||state.result.aperture_conditions?.default_condition_id||"",field:$("field").value||"outer-ne",chart:$("chart").value||"resolution",stage:$("stage").value||"isp"})}">${esc(state.options?.sensor_operating_modes?.modes.find(v=>v.id===r.operating_mode_id)?.label||r.operating_mode_id)} · ${fmt(r.fps)} FPS</a>`).join(" · ")+'</p>';}
  function sensorShutterAxes(){const parse=(id,name,min,max)=>{const parts=$(id).value.trim().split(",").map(v=>v.trim()),values=parts.map(Number);if(parts.some(v=>!v)||values.length<1||values.length>8||values.some(v=>!finite(v)||v<min||v>max)||values.some((v,i)=>i>0&&values[i-1]>=v))throw Error(`${name}은 ${min}–${max} 범위의 1–8개 값을 중복 없이 오름차순으로 입력하세요.`);return values;},luminance_cd_m2=parse("sensor-shutter-luminances","장면 휘도",.1,100000),object_speed_m_s=parse("sensor-shutter-speeds","수평 속도",0,50),exposure_ms=parse("sensor-shutter-exposures","노출",.1,100),line_time_us=parse("sensor-shutter-line-times","Line time",0,100),f_numbers=parse("sensor-shutter-fnumbers","F-number",2.75,11),distance=$("sensor-shutter-distance").value.trim(),object_distance_m=Number(distance);if(!distance||!finite(object_distance_m)||object_distance_m<1||object_distance_m>1000)throw Error("속도 환산 거리는 1–1000 m이어야 합니다.");if(line_time_us.some(v=>v>0&&v<.1))throw Error("양수 line time은 0.1–100 µs/행이어야 합니다.");if(line_time_us[0]!==0||line_time_us.length<2)throw Error("동일 노출 GS 기준인 0 µs/행과 양수인 line time을 함께 넣으세요.");const available=state.options?.recipes?.aperture_sweep?.f_numbers||(state.result?.comparison_mode==="aperture_sweep"?state.result.aperture_sweep?.rows.map(r=>r.f_number):null);if(available&&f_numbers.some(f=>!available.includes(f)))throw Error("원본 조리개 탐색에 보존된 F-number만 선택하세요.");const cells=luminance_cd_m2.length*object_speed_m_s.length;if(cells>24||cells*exposure_ms.length>36||cells*exposure_ms.length*line_time_us.length*f_numbers.length>216)throw Error("지도 24칸, 지도×노출 36개, 전체 F×노출×line time 계산 216개 이내로 설정하세요.");const modeId=$("sensor-shutter-mode")?.value;if(modeId){const fps=Number($("sensor-shutter-fps").value),m=state.options?.sensor_operating_modes?.modes.find(v=>v.id===modeId);if(!m||!finite(fps)||fps<m.min_fps||fps>m.max_fps)throw Error("선택 모드의 FPS 범위를 확인하세요.");return{luminance_cd_m2,object_speed_m_s,object_distance_m,exposure_ms,line_time_us:[0,m.line_time_us],f_numbers,operating_mode_id:modeId,fps};}return{luminance_cd_m2,object_speed_m_s,object_distance_m,exposure_ms,line_time_us,f_numbers};}
  async function submitSensorShutter(useControls=false){if(state.submitting||state.job&&!ended(state.job.status))return;const recipe=state.options?.recipes?.sensor_shutter,source=conditionSourceId();if(!recipe||!source)throw Error("완료된 조리개 원본과 센서 전체 행 시간축 명세가 필요합니다.");const axes=sensorShutterAxes(),cache=isSensorShutterResult()?state.loaded.id:null,payload={...recipe,...axes,source_run_id:source,...(cache?{located_source_run_id:cache}:{}),...(useControls?{selection_policy:sweepPolicy()}:{})};state.submitting=true;buttons();try{const job=await api(ROOT+"/studies",payload);state.job=job;state.pendingBaseline={jobId:job.id,baselineId:""};renderJob();notice(`센서 전체 시간축 계산 제출 · ${job.id}. 센서 형상·ROI 행 위치·근거를 고정하고 실제 RAW·ISP를 새로 계산합니다.`);schedulePoll();}finally{state.submitting=false;buttons();}}
  function initSensorShutterControls(){if($("sensor-shutter-mode"))$("sensor-shutter-mode").onchange=()=>{state.sensorModeInputEdited=true;renderSensorModeInput(true);notice("미제출 모드 변경 · 현재 보존 영상은 그대로입니다.");};if($("sensor-shutter-fps"))$("sensor-shutter-fps").oninput=()=>{state.sensorModeInputEdited=true;renderSensorModeInput();};$("sensor-shutter-study").onclick=()=>submitSensorShutter().catch(e=>notice(e.message,true));for(const id of["sensor-shutter-luminances","sensor-shutter-speeds","sensor-shutter-exposures","sensor-shutter-distance","sensor-shutter-line-times","sensor-shutter-fnumbers"])$(id).oninput=()=>{state.sensorShutterAxesEdited=true;notice("미제출 전체 센서 timing 설정 · 보존 결과는 변경하지 않았습니다. 실행하면 형상·시각·근거를 고정한 새 계산이 생성됩니다.");};$("sensor-timing-input-profile").textContent="센서 active 형상·시야별 ROI 행 위치와 각 값의 출처는 제출 시 고정하여 결과에 보존합니다. 형상과 제품 timing의 확인 상태는 각각 표시합니다.";}
